1	import { useState } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	import { useAuth } from "@/hooks/useAuth";
5	import {
6	  Dialog,
7	  DialogContent,
8	  DialogDescription,
9	  DialogHeader,
10	  DialogTitle,
11	  DialogTrigger,
12	} from "@/components/ui/dialog";
13	import {
14	  AlertDialog,
15	  AlertDialogAction,
16	  AlertDialogCancel,
17	  AlertDialogContent,
18	  AlertDialogDescription,
19	  AlertDialogFooter,
20	  AlertDialogHeader,
21	  AlertDialogTitle,
22	} from "@/components/ui/alert-dialog";
23	import { Button } from "@/components/ui/button";
24	import { Badge } from "@/components/ui/badge";
25	import { toast } from "sonner";
26	import { Crown, Loader2, Zap, Check, ArrowRight, ArrowDown, CalendarClock, XCircle, CreditCard } from "lucide-react";
27	import { format } from "date-fns";
28	
29	interface SubscriptionDialogProps {
30	  trigger?: React.ReactNode;
31	}
32	
33	const SubscriptionDialog = ({ trigger }: SubscriptionDialogProps) => {
34	  const { user, profile, refreshProfile } = useAuth();
35	  const [open, setOpen] = useState(false);
36	  const [buying, setBuying] = useState<string | null>(null);
37	  const [cancelling, setCancelling] = useState(false);
38	  const [confirmAction, setConfirmAction] = useState<{
39	    type: "upgrade" | "downgrade" | "cancel_subscription";
40	    planId?: string;
41	    planName?: string;
42	    price?: number;
43	  } | null>(null);
44	  const [downgrading, setDowngrading] = useState(false);
45	
46	  const currentPlan = profile?.plan ?? "free";
47	  const isPaid = currentPlan !== "free";
48	  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
49	    ? new Date((profile as any).subscription_ends_at)
50	    : null;
51	  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
52	  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;
53	
54	  const { data: plans } = useQuery({
55	    queryKey: ["subscription_plans_active"],
56	    queryFn: async () => {
57	      const { data, error } = await supabase
58	        .from("plans")
59	        .select("*")
60	        .eq("active", true)
61	        .order("price");
62	      if (error) throw error;
63	      return data;
64	    },
65	  });
66	
67	  const { data: config } = useQuery({
68	    queryKey: ["platform_config_payg"],
69	    queryFn: async () => {
70	      const { data, error } = await supabase
71	        .from("platform_config")
72	        .select("*")
73	        .limit(1)
74	        .single();
75	      if (error) return null;
76	      return data;
77	    },
78	  });
79	
80	  const paygCost = (config as any)?.payg_per_resume_cost ?? 0.07;
81	
82	  const handleSubscribe = async (planId: string) => {
83	    if (!user) return;
84	    setBuying(planId);
85	
86	    try {
87	      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
88	        body: {
89	          plan_id: planId,
90	          return_url: `${window.location.origin}/payment/callback`,
91	        },
92	      });
93	
94	      if (error) throw error;
95	
96	      if (!data?.checkout_url) {
97	        toast.error(data?.error || "Failed to create checkout session");
98	        return;
99	      }
100	
101	      // Redirect to Dodo hosted checkout
102	      window.location.href = data.checkout_url;
103	    } catch (err: any) {
104	      toast.error(err.message);
105	    } finally {
106	      setBuying(null);
107	    }
108	  };
109	
110	  const handleCancelSubscription = async () => {
111	    setCancelling(true);
112	    try {
113	      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
114	      if (error) throw error;
115	      toast.success("Subscription will cancel at the end of your current billing period.");
116	      await refreshProfile();
117	      setConfirmAction(null);
118	    } catch (err: any) {
119	      toast.error("Failed to cancel: " + err.message);
120	    } finally {
121	      setCancelling(false);
122	    }
123	  };
124	
125	  const handleDowngradeToPayg = async () => {
126	    setDowngrading(true);
127	    try {
128	      if (hasActiveSubscription) {
129	        const { data, error: cancelError } = await supabase.functions.invoke("cancel-dodo-subscription", {});
130	        if (cancelError || data?.error) {
131	          toast.error("Could not cancel subscription with payment provider. Please try again or contact support.");
132	          setDowngrading(false);
133	          return;
134	        }
135	      }
136	      const { error } = await supabase
137	        .from("profiles")
138	        .update({ plan: "free", subscription_ends_at: null, dodo_subscription_id: null } as any)
139	        .eq("user_id", user?.id);
140	      if (error) throw error;
141	      toast.success("Switched to Pay As You Go. Your remaining credits are preserved.");
142	      await refreshProfile();
143	      setConfirmAction(null);
144	    } catch (err: any) {
145	      toast.error("Failed to downgrade: " + err.message);
146	    } finally {
147	      setDowngrading(false);
148	    }
149	  };
150	
151	  const handleConfirmedAction = () => {
152	    if (!confirmAction) return;
153	    if (confirmAction.type === "upgrade" && confirmAction.planId) {
154	      handleSubscribe(confirmAction.planId);
155	      setConfirmAction(null);
156	    } else if (confirmAction.type === "downgrade") {
157	      handleDowngradeToPayg();
158	    } else if (confirmAction.type === "cancel_subscription") {
159	      handleCancelSubscription();
160	    }
161	  };
162	
163	  return (
164	    <>
165	      <Dialog open={open} onOpenChange={setOpen}>
166	        <DialogTrigger asChild>
167	          {trigger || (
168	            <Button variant="outline" size="sm" className="gap-1.5">
169	              <Crown className="h-3.5 w-3.5" />
170	              Upgrade Plan
171	            </Button>
172	          )}
173	        </DialogTrigger>
174	        <DialogContent className="sm:max-w-lg">
175	          <DialogHeader>
176	            <DialogTitle className="flex items-center gap-2">
177	              <CreditCard className="h-5 w-5 text-primary" />
178	              Choose Your Plan
179	            </DialogTitle>
180	            <DialogDescription>
181	              {isPaid
182	                ? "Manage your subscription or switch plans."
183	                : "Upgrade to save on every resume ranked. All plans auto-renew."}
184	            </DialogDescription>
185	          </DialogHeader>
186	
187	          {/* Current Plan Banner */}
188	          <div className="rounded-lg border border-border bg-muted/50 px-4 py-3 flex items-center gap-3">
189	            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/15">
190	              {isPaid ? <Crown className="h-4 w-4 text-primary" /> : <Zap className="h-4 w-4 text-primary" />}
191	            </div>
192	            <div className="flex-1">
193	              <p className="text-sm font-medium text-foreground">
194	                Current: {isPaid ? currentPlan : "Pay As You Go"}
195	              </p>
196	              <p className="text-xs text-muted-foreground">
197	                {isPaid
198	                  ? subscriptionEndsAt
199	                    ? isExpired
200	                      ? "Your subscription has expired"
201	                      : hasActiveSubscription
202	                        ? `Auto-renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
203	                        : `Expires ${format(subscriptionEndsAt, "MMM d, yyyy")}`
204	                    : "You're saving on every resume!"
205	                  : `$${paygCost}/resume • Upgrade to save more`}
206	              </p>
207	            </div>
208	            {isPaid && subscriptionEndsAt && !isExpired && (
209	              <Badge variant="secondary" className="text-xs gap-1">
210	                <CalendarClock className="h-3 w-3" />
211	                {format(subscriptionEndsAt, "MMM d")}
212	              </Badge>
213	            )}
214	            {isPaid && isExpired && (
215	              <Badge variant="destructive" className="text-xs">Expired</Badge>
216	            )}
217	            {!isPaid && (
218	              <Badge variant="secondary" className="text-xs">Active</Badge>
219	            )}
220	          </div>
221	
222	          {/* Cancel Subscription Button */}
223	          {isPaid && hasActiveSubscription && !isExpired && (
224	            <Button
225	              variant="outline"
226	              size="sm"
227	              className="gap-1.5 text-xs border-destructive/30 text-destructive hover:bg-destructive/10"
228	              onClick={() => setConfirmAction({ type: "cancel_subscription" })}
229	              disabled={cancelling}
230	            >
231	              {cancelling ? <Loader2 className="h-3 w-3 animate-spin" /> : <XCircle className="h-3 w-3" />}
232	              Cancel Auto-Renewal
233	            </Button>
234	          )}
235	
236	          {/* PAYG Card */}
237	          <div className={`rounded-lg border p-4 ${!isPaid ? "border-primary/50 bg-primary/5" : "border-border"}`}>
238	            <div className="flex items-center justify-between">
239	              <div>
240	                <div className="flex items-center gap-2">
241	                  <p className="font-semibold text-foreground">Pay As You Go</p>
242	                  {!isPaid && <Badge variant="default" className="text-[11px] px-1.5 py-0">Current</Badge>}
243	                </div>
244	                <p className="text-xs text-muted-foreground mt-1">No commitment • Buy credits anytime</p>
245	              </div>
246	              <div className="flex items-center gap-3">
247	                <div className="text-right">
248	                  <p className="text-lg font-bold text-foreground">$0</p>
249	                  <p className="text-xs text-muted-foreground">/month</p>
250	                </div>
251	                {isPaid && (
252	                  <Button
253	                    variant="outline"
254	                    size="sm"
255	                    className="gap-1 h-8 text-xs border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
256	                    onClick={() => setConfirmAction({ type: "downgrade" })}
257	                  >
258	                    <ArrowDown className="h-3 w-3" />
259	                    Switch
260	                  </Button>
261	                )}
262	              </div>
263	            </div>
264	            <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
265	              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${paygCost}/resume</span>
266	              <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
267	            </div>
268	          </div>
269	
270	          {/* Subscription Plans */}
271	          <div className="space-y-3">
272	            {plans?.map((plan: any, idx: number) => {
273	              const isCurrentPlan = currentPlan === plan.name;
274	              const savings = paygCost > 0 ? Math.round(((paygCost - (plan.per_resume_cost ?? 0.05)) / paygCost) * 100) : 0;
275	              const isPopular = idx === Math.floor((plans.length - 1) / 2);
276	
277	              return (
278	                <div
279	                  key={plan.id}
280	                  className={`relative rounded-lg border p-4 transition-colors ${
281	                    isCurrentPlan
282	                      ? "border-primary/50 bg-primary/5"
283	                      : "border-border hover:border-primary/30 hover:bg-accent/30"
284	                  }`}
285	                >
286	                  {isPopular && !isCurrentPlan && (
287	                    <Badge className="absolute -top-2.5 right-3 bg-primary text-primary-foreground text-[11px] px-2 py-0.5">
288	                      Popular
289	                    </Badge>
290	                  )}
291	                  <div className="flex items-center justify-between">
292	                    <div>
293	                      <div className="flex items-center gap-2">
294	                        <p className="font-semibold text-foreground">{plan.name}</p>
295	                        {isCurrentPlan && <Badge variant="default" className="text-[11px] px-1.5 py-0">Current</Badge>}
296	                        {savings > 0 && !isCurrentPlan && (
297	                          <Badge variant="secondary" className="text-[11px] px-1.5 py-0 text-primary">
298	                            Save {savings}%
299	                          </Badge>
300	                        )}
301	                      </div>
302	                      <p className="text-xs text-muted-foreground mt-1">
303	                        {plan.billing_type} • {plan.credits} credits • Auto-renews
304	                      </p>
305	                    </div>
306	                    <div className="text-right">
307	                      <p className="text-lg font-bold text-foreground">${plan.price}</p>
308	                      <p className="text-xs text-muted-foreground">/{plan.billing_type === "yearly" ? "year" : "mo"}</p>
309	                    </div>
310	                  </div>
311	                  <div className="mt-3 flex items-center justify-between">
312	                    <div className="flex items-center gap-4 text-xs text-muted-foreground">
313	                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> ${plan.per_resume_cost ?? 0.05}/resume</span>
314	                      <span className="flex items-center gap-1"><Check className="h-3 w-3 text-primary" /> Credit top-ups</span>
315	                    </div>
316	                    {!isCurrentPlan && (
317	                      <Button
318	                        size="sm"
319	                        onClick={() =>
320	                          setConfirmAction({
321	                            type: "upgrade",
322	                            planId: plan.id,
323	                            planName: plan.name,
324	                            price: plan.price,
325	                          })
326	                        }
327	                        disabled={buying === plan.id}
328	                        className="gap-1 h-8"
329	                      >
330	                        {buying === plan.id ? (
331	                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
332	                        ) : (
333	                          <>
334	                            Subscribe <ArrowRight className="h-3 w-3" />
335	                          </>
336	                        )}
337	                      </Button>
338	                    )}
339	                  </div>
340	                </div>
341	              );
342	            })}
343	            {(!plans || plans.length === 0) && (
344	              <p className="text-sm text-muted-foreground text-center py-4">
345	                No subscription plans available right now. Please try again later or contact support.
346	              </p>
347	            )}
348	          </div>
349	
350	          <p className="text-[11px] text-muted-foreground text-center pt-1">
351	            All plans auto-renew. Cancel anytime before your next billing date.
352	          </p>
353	        </DialogContent>
354	      </Dialog>
355	
356	      {/* Confirmation AlertDialog */}
357	      <AlertDialog open={confirmAction !== null} onOpenChange={(o) => !o && setConfirmAction(null)}>
358	        <AlertDialogContent>
359	          <AlertDialogHeader>
360	            <AlertDialogTitle>
361	              {confirmAction?.type === "upgrade"
362	                ? `Subscribe to ${confirmAction.planName}?`
363	                : confirmAction?.type === "cancel_subscription"
364	                  ? "Cancel Auto-Renewal?"
365	                  : "Switch to Pay As You Go?"}
366	            </AlertDialogTitle>
367	            <AlertDialogDescription>
368	              {confirmAction?.type === "upgrade" ? (
369	                <>
370	                  You'll be redirected to our secure checkout page to complete payment of{" "}
371	                  <span className="font-semibold text-foreground">${confirmAction.price}</span>.
372	                  Your subscription will auto-renew each billing period.
373	                </>
374	              ) : confirmAction?.type === "cancel_subscription" ? (
375	                <>
376	                  Your subscription will remain active until the end of your current billing period.
377	                  After that, you'll be switched to Pay As You Go pricing. Your remaining credits will be preserved.
378	                </>
379	              ) : (
380	                <>
381	                  You'll switch back to Pay As You Go pricing at <span className="font-semibold text-foreground">${paygCost}/resume</span>.
382	                  Your remaining credits will be preserved and you can still purchase credit top-ups.
383	                  {hasActiveSubscription && " Your active subscription will also be cancelled."}
384	                </>
385	              )}
386	            </AlertDialogDescription>
387	          </AlertDialogHeader>
388	          <AlertDialogFooter>
389	            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
390	            <AlertDialogAction
391	              onClick={handleConfirmedAction}
392	              disabled={downgrading || cancelling}
393	              className={confirmAction?.type !== "upgrade" ? "bg-destructive text-destructive-foreground hover:bg-destructive/90" : ""}
394	            >
395	              {(downgrading || cancelling) && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
396	              {confirmAction?.type === "upgrade"
397	                ? "Proceed to Payment"
398	                : confirmAction?.type === "cancel_subscription"
399	                  ? "Cancel Auto-Renewal"
400	                  : "Confirm Downgrade"}
401	            </AlertDialogAction>
402	          </AlertDialogFooter>
403	        </AlertDialogContent>
404	      </AlertDialog>
405	    </>
406	  );
407	};
408	
