input.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import {
  Crown,
  Loader2,
  Zap,
  Check,
  ArrowRight,
  XCircle,
  CalendarClock,
  Sparkles,
  RefreshCw,
} from "lucide-react";
import { format } from "date-fns";

interface SubscriptionDialogProps {
  trigger?: React.ReactNode;
}

const PLAN_FEATURES: Record<string, string[]> = {
  default: [
    "All core ranking features",
    "Credit top-ups available",
    "Email resume ingestion",
    "Priority support",
  ],
};

const SubscriptionDialog = ({ trigger }: SubscriptionDialogProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const [open, setOpen] = useState(false);
  const [buying, setBuying] = useState<string | null>(null);
  const [cancelling, setCancelling] = useState(false);
  const [downgrading, setDowngrading] = useState(false);
  const [confirmAction, setConfirmAction] = useState<{
    type: "upgrade" | "downgrade" | "cancel_subscription";
    planId?: string;
    planName?: string;
    price?: number;
  } | null>(null);

  const currentPlan = profile?.plan ?? "free";
  const isPaid = currentPlan !== "free";
  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
    ? new Date((profile as any).subscription_ends_at)
    : null;
  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;

  const { data: plans } = useQuery({
    queryKey: ["subscription_plans_active"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("plans")
        .select("*")
        .eq("active", true)
        .order("price");
      if (error) throw error;
      return data;
    },
  });

  const { data: config } = useQuery({
    queryKey: ["platform_config_payg"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("*")
        .limit(1)
        .single();
      if (error) return null;
      return data;
    },
  });

  const paygCost = (config as any)?.payg_per_resume_cost ?? 0.07;

  const handleSubscribe = async (planId: string) => {
    if (!user) return;
    setBuying(planId);
    try {
      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
        body: {
          plan_id: planId,
          return_url: `${window.location.origin}/payment/callback`,
        },
      });
      if (error) throw error;
      if (!data?.checkout_url) {
        toast.error(data?.error || "Failed to create checkout session");
        return;
      }
      window.location.href = data.checkout_url;
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Checkout failed");
    } finally {
      setBuying(null);
    }
  };

  const handleCancelSubscription = async () => {
    setCancelling(true);
    try {
      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
      if (error) throw error;
      toast.success("Auto-renewal cancelled. Your plan stays active until the billing period ends.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: unknown) {
      toast.error("Failed to cancel: " + (err instanceof Error ? err.message : "Unknown error"));
    } finally {
      setCancelling(false);
    }
  };

  const handleDowngradeToPayg = async () => {
    setDowngrading(true);
    try {
      if (hasActiveSubscription) {
        const { data, error: cancelError } = await supabase.functions.invoke(
          "cancel-dodo-subscription",
          {}
        );
        if (cancelError || data?.error) {
          toast.error(
            "Could not cancel subscription with payment provider. Please try again or contact support."
          );
          setDowngrading(false);
          return;
        }
      }
      const { error } = await supabase
        .from("profiles")
        .update({
          plan: "free",
          subscription_ends_at: null,
          dodo_subscription_id: null,
        } as any)
        .eq("user_id", user?.id);
      if (error) throw error;
      toast.success("Switched to Pay As You Go. Your remaining credits are preserved.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: unknown) {
      toast.error(
        "Failed to downgrade: " + (err instanceof Error ? err.message : "Unknown error")
      );
    } finally {
      setDowngrading(false);
    }
  };

  const handleConfirmedAction = () => {
    if (!confirmAction) return;
    if (confirmAction.type === "upgrade" && confirmAction.planId) {
      handleSubscribe(confirmAction.planId);
      setConfirmAction(null);
    } else if (confirmAction.type === "downgrade") {
      handleDowngradeToPayg();
    } else if (confirmAction.type === "cancel_subscription") {
      handleCancelSubscription();
    }
  };

  // Determine "popular" plan (middle one)
  const popularIdx =
    plans && plans.length > 1 ? Math.floor((plans.length - 1) / 2) : -1;

  return (
    <>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          {trigger || (
            <Button variant="outline" size="sm" className="gap-1.5">
              <Crown className="h-3.5 w-3.5" />
              Upgrade Plan
            </Button>
          )}
        </DialogTrigger>

        <DialogContent className="sm:max-w-2xl p-0 gap-0 overflow-hidden">
          {/* Header */}
          <DialogHeader className="px-6 pt-6 pb-4">
            <DialogTitle className="flex items-center gap-2 text-base font-semibold">
              <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-primary/10">
                <Sparkles className="h-3.5 w-3.5 text-primary" />
              </span>
              Choose Your Plan
            </DialogTitle>
            <p className="text-sm text-muted-foreground mt-0.5">
              {isPaid
                ? "Manage your subscription or switch plans."
                : "Unlock lower per-resume cost with a subscription. All plans auto-renew."}
            </p>
          </DialogHeader>

          <Separator />

          {/* Current plan status bar */}
          <div className="px-6 py-3 flex items-center gap-3 bg-muted/40">
            <div className="flex h-7 w-7 items-center justify-center rounded-md bg-background border border-border">
              {isPaid ? (
                <Crown className="h-3.5 w-3.5 text-primary" />
              ) : (
                <Zap className="h-3.5 w-3.5 text-muted-foreground" />
              )}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-medium text-foreground leading-tight">
                {isPaid ? `${currentPlan} plan` : "Pay As You Go"}
              </p>
              <p className="text-[11px] text-muted-foreground leading-tight">
                {isPaid
                  ? subscriptionEndsAt
                    ? isExpired
                      ? "Your subscription has expired"
                      : hasActiveSubscription
                      ? `Auto-renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
                      : `Active until ${format(subscriptionEndsAt, "MMM d, yyyy")}`
                    : "Subscription active"
                  : `$${paygCost} per resume ranked`}
              </p>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              {isPaid && subscriptionEndsAt && !isExpired && (
                <Badge variant="secondary" className="text-[11px] gap-1 h-5 px-1.5">
                  <CalendarClock className="h-2.5 w-2.5" />
                  {format(subscriptionEndsAt, "MMM d")}
                </Badge>
              )}
              {isPaid && isExpired && (
                <Badge variant="destructive" className="text-[11px] h-5 px-1.5">
                  Expired
                </Badge>
              )}
              {isPaid && hasActiveSubscription && !isExpired && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-6 px-2 text-[11px] text-destructive hover:text-destructive hover:bg-destructive/10 gap-1"
                  onClick={() => setConfirmAction({ type: "cancel_subscription" })}
                  disabled={cancelling}
                >
                  {cancelling ? (
                    <Loader2 className="h-3 w-3 animate-spin" />
                  ) : (
                    <XCircle className="h-3 w-3" />
                  )}
                  Cancel renewal
                </Button>
              )}
            </div>
          </div>

          <Separator />

          {/* Plan cards */}
          <div className="p-6">
            <div
              className={`grid gap-3 ${
                plans && plans.length >= 3
                  ? "sm:grid-cols-3"
                  : plans && plans.length === 2
                  ? "sm:grid-cols-2"
                  : "grid-cols-1"
              }`}
            >
              {/* PAYG card */}
              <div
                className={`relative flex flex-col rounded-xl border p-4 transition-all ${
                  !isPaid
                    ? "border-primary/40 bg-primary/5 ring-1 ring-primary/20"
                    : "border-border bg-card hover:border-border/80"
                }`}
              >
                {!isPaid && (
                  <span className="absolute -top-2.5 left-3">
                    <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                      <Check className="h-2.5 w-2.5" />
                      Current
                    </Badge>
                  </span>
                )}
                <div className="mb-3">
                  <p className="text-sm font-semibold text-foreground">Pay As You Go</p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">No commitment</p>
                </div>
                <div className="mb-4">
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-bold text-foreground">$0</span>
                    <span className="text-xs text-muted-foreground">/mo</span>
                  </div>
                  <p className="text-[11px] text-muted-foreground mt-0.5">
                    ${paygCost}/resume
                  </p>
                </div>
                <ul className="space-y-1.5 flex-1 mb-4">
                  <li className="flex items-start gap-1.5 text-[11px] text-muted-foreground">
                    <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                    Buy credits anytime
                  </li>
                  <li className="flex items-start gap-1.5 text-[11px] text-muted-foreground">
                    <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                    Credits never expire
                  </li>
                  <li className="flex items-start gap-1.5 text-[11px] text-muted-foreground">
                    <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                    Full feature access
                  </li>
                </ul>
                {isPaid && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full h-8 text-xs gap-1 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => setConfirmAction({ type: "downgrade" })}
                    disabled={downgrading}
                  >
                    {downgrading ? (
                      <Loader2 className="h-3 w-3 animate-spin" />
                    ) : (
                      <RefreshCw className="h-3 w-3" />
                    )}
                    Switch to PAYG
                  </Button>
                )}
                {!isPaid && (
                  <div className="h-8 flex items-center justify-center">
                    <span className="text-[11px] text-muted-foreground">Your current plan</span>
                  </div>
                )}
              </div>

              {/* Subscription plan cards */}
              {plans?.map((plan: any, idx: number) => {
                const isCurrentPlan = currentPlan === plan.name;
                const isPopular = idx === popularIdx;
                const perResumeCost = plan.per_resume_cost ?? 0.05;
                const savingsPct =
                  paygCost > 0
                    ? Math.round(((paygCost - perResumeCost) / paygCost) * 100)
                    : 0;
                const features: string[] =
                  PLAN_FEATURES[plan.name] || PLAN_FEATURES["default"];

                return (
                  <div
                    key={plan.id}
                    className={`relative flex flex-col rounded-xl border p-4 transition-all ${
                      isCurrentPlan
                        ? "border-primary/40 bg-primary/5 ring-1 ring-primary/20"
                        : isPopular
                        ? "border-primary/25 bg-card shadow-sm"
                        : "border-border bg-card hover:border-border/80"
                    }`}
                  >
                    {/* Badges */}
                    {isPopular && !isCurrentPlan && (
                      <span className="absolute -top-2.5 left-3">
                        <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                          <Sparkles className="h-2.5 w-2.5" />
                          Popular
                        </Badge>
                      </span>
                    )}
                    {isCurrentPlan && (
                      <span className="absolute -top-2.5 left-3">
                        <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                          <Check className="h-2.5 w-2.5" />
                          Current
                        </Badge>
                      </span>
                    )}

                    <div className="mb-3">
                      <div className="flex items-center gap-1.5">
                        <p className="text-sm font-semibold text-foreground capitalize">
                          {plan.name}
                        </p>
                        {savingsPct > 0 && !isCurrentPlan && (
                          <Badge
                            variant="secondary"
                            className="text-[10px] h-4 px-1 py-0 text-primary bg-primary/10"
                          >
                            Save {savingsPct}%
                          </Badge>
                        )}
                      </div>
                      <p className="text-[11px] text-muted-foreground mt-0.5 capitalize">
                        {plan.billing_type} • {plan.credits} credits
                      </p>
                    </div>

                    <div className="mb-4">
                      <div className="flex items-baseline gap-1">
                        <span className="text-2xl font-bold text-foreground">
                          ${plan.price}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          /{plan.billing_type === "yearly" ? "yr" : "mo"}
                        </span>
                      </div>
                      <p className="text-[11px] text-muted-foreground mt-0.5">
                        ${perResumeCost}/resume
                      </p>
                    </div>

                    <ul className="space-y-1.5 flex-1 mb-4">
                      {features.map((f) => (
                        <li
                          key={f}
                          className="flex items-start gap-1.5 text-[11px] text-muted-foreground"
                        >
                          <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                          {f}
                        </li>
                      ))}
                    </ul>

                    {isCurrentPlan ? (
                      <div className="h-8 flex items-center justify-center">
                        <span className="text-[11px] text-muted-foreground">
                          Your current plan
                        </span>
                      </div>
                    ) : (
                      <Button
                        size="sm"
                        className="w-full h-8 text-xs gap-1"
                        onClick={() =>
                          setConfirmAction({
                            type: "upgrade",
                            planId: plan.id,
                            planName: plan.name,
                            price: plan.price,
                          })
                        }
                        disabled={buying === plan.id}
                      >
                        {buying === plan.id ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <>
                            Subscribe
                            <ArrowRight className="h-3 w-3" />
                          </>
                        )}
                      </Button>
                    )}
                  </div>
                );
              })}

              {(!plans || plans.length === 0) && (
                <div className="col-span-full text-center py-8 text-sm text-muted-foreground">
                  No subscription plans available right now.
                </div>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="px-6 pb-5 text-center">
            <p className="text-[11px] text-muted-foreground">
              All subscriptions auto-renew. Cancel anytime before your next billing date. Credits
              from expired plans are preserved.
            </p>
          </div>
        </DialogContent>
      </Dialog>

      {/* Confirm dialog */}
      <AlertDialog
        open={confirmAction !== null}
        onOpenChange={(o) => !o && setConfirmAction(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {confirmAction?.type === "upgrade"
                ? `Subscribe to ${confirmAction.planName}?`
                : confirmAction?.type === "cancel_subscription"
                ? "Cancel Auto-Renewal?"
                : "Switch to Pay As You Go?"}
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div>
                {confirmAction?.type === "upgrade" ? (
                  <span>
                    You'll be redirected to our secure checkout to complete payment of{" "}
                    <strong className="text-foreground font-semibold">
                      ${confirmAction.price}
                    </strong>
                    . Your subscription will auto-renew each billing period.
                  </span>
                ) : confirmAction?.type === "cancel_subscription" ? (
                  <span>
                    Your plan stays active until the end of your current billing period. After
                    that you'll move to Pay As You Go. Your remaining credits are preserved.
                  </span>
                ) : (
                  <span>
                    You'll switch to Pay As You Go at{" "}
                    <strong className="text-foreground font-semibold">${paygCost}/resume</strong>
                    . Your remaining credits are preserved and you can still purchase top-ups.
                    {hasActiveSubscription && " Your active subscription will also be cancelled."}
                  </span>
                )}
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmedAction}
              disabled={downgrading || cancelling}
              className={
                confirmAction?.type !== "upgrade"
                  ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  : ""
              }
            >
              {(downgrading || cancelling) && (
                <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
              )}
              {confirmAction?.type === "upgrade"
                ? "Proceed to Payment"
                : confirmAction?.type === "cancel_subscription"
                ? "Cancel Auto-Renewal"
                : "Confirm Downgrade"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
};

export default SubscriptionDialog;
